        {
            tomcat7Runner.extractDirectory = line.getOptionValue( extractDirectory.getOpt() );
        }

        if ( line.hasOption( sessionManagerFactoryClassName.getOpt() ) )
        {
            tomcat7Runner.sessionManagerFactoryClassName =
