				retValue = getCharacterValueWithinRange(annotations,
						attributeMetadata);

			}

			if (retValue == null) {
				retValue = strategy.getCharacter(attributeMetadata);
			}

		} else {

			throw new IllegalArgumentException(
					String.format("%s is unsupported primitive type",
							primitiveClass));
		}

		return retValue;
	}

