                String n = name.trim();
                CollectedStatistics cs = stats.get(n);

                if ( cs == null )
                    continue;

                JmxStatistics js = new JmxStatistics();
                js.count = cs.getInvocations();
                js.max = cs.getMax();
                js.min = cs.getMin();
                js.mean = cs.getAverageMS();
                js.perc95 = cs.getPercentile( 95 );
