    private void parseNetworkNode(StringBuffer line) {
        line.replace(0, 5, "");
        line.trimToSize();
        String[] lineArray = line.toString().split("\\s+");

        nodes = Arrays.asList(lineArray);

        for (String nodeString : nodes) {
