		//onStep will need to know base depth
	    //act.getPosition().set(x, y, Level.tm.getForegroundDepth() - y + depth);
		act.getPosition().set(x, y, (Level.tm == null) ? 0 : Level.tm.getForegroundDepth() + depth);
	}

