		Pangine.getEngine().getAudio().stopMusic();
    	music.startSound();
	}

	@Override
	public boolean onPause() {
		if (Pangine.getEngine().isPaused()) {
			return true;
		} else if (Panscreen.get() instanceof PlatformScreen && hud != null) {
			PlayerScreen.promptQuit(hud);
